def test_interview_questions_count():
    """Verify 17 questions generated correctly."""
    questions = generate_interview_questions("Test Person")
    assert "questions" in questions
    # Should have all 17 question categories
    assert len(questions["questions"]) == 17, f"Expected 17 questions, got {len(questions['questions'])}"


def test_interview_questions_structure():
    """Verify question structure has required fields."""
    questions = generate_interview_questions("Marcus Aurelius")
    
    for q in questions["questions"]:
        assert "id" in q, "Question missing 'id' field"
        assert "header" in q, "Question missing 'header' field"
        assert "text" in q, "Question missing 'text' field"
        assert "options" in q, "Question missing 'options' field"
        assert "multi_select" in q, "Question missing 'multi_select' field"
        
        # Verify options structure
        for opt in q["options"]:
            assert "label" in opt, "Option missing 'label'"
            assert "description" in opt, "Option missing 'description'"


