def test_multi_select_questions():
    """Verify multi-select questions are correctly marked."""
    questions = generate_interview_questions("Test Person")
    
    multi_select_ids = ["formative_events", "prime_events", "late_events", 
                        "personality", "emotional_coloring", "family_structure", 
                        "modern_reference"]
    
    for q in questions["questions"]:
        if q["id"] in multi_select_ids:
            assert q["multi_select"] is True, f"Question {q['id']} should be multi-select"
        else:
            assert q["multi_select"] is False, f"Question {q['id']} should be single-select"


