def test_emotional_layers_generation():
    """Verify emotional layers are generated from life events."""
    mock_responses = {
        "responses": {
            "formative_events": ["Loss of parent/family", "Privileged education"],
            "prime_events": ["War/Conflict", "Political Power"],
            "late_events": ["Reflection/Writing"],
            "family_structure": ["Eldest child"],
            "religion": "Stoic philosophy",
            "religiosity_level": "Devout/Practicing",
            "cultural_emotional_norms": "Greco-Roman Stoic",
            "current_persona_age": "Elder (65+)",
            "recent_impactful_event": "None significant",
            "suppression_level": "Moderately suppressed",
            "social_class": "Aristocracy/Nobility",
            "personality": ["Stoic/Measured"],
            "emotional_coloring": [],
            "geographic_origin": "Rome",
            "time_period": "Ancient",
            "birth_death_years": "121-180",
            "modern_reference": [],
        }
    }
    
    design = process_interview_results("Test", mock_responses)
    layers = design["voice_design"]["emotional_layers"]
    
    assert "foundational" in layers
    assert "defining" in layers
    assert "current" in layers
    
    # Verify foundational layer includes early loss
    assert len(layers["foundational"]) > 0
    assert any("grief" in layer.lower() for layer in layers["foundational"])
    
    # Verify defining layer includes political power
    assert len(layers["defining"]) > 0
    
    # Verify current layer includes reflection
    assert len(layers["current"]) > 0


def test_accent_database_coverage():
    """Verify accent database has expected entries."""
    expected_regions = [
        "boston_colonial",
        "charleston_southern",
        "philadelphia_colonial",
        "london_victorian",
        "rome_classical",
        "hawaii_modern",
    ]
    
    for region in expected_regions:
        assert region in ACCENT_DATABASE, f"Missing accent: {region}"
        accent = ACCENT_DATABASE[region]
        assert "region" in accent
        assert "era" in accent
        assert "characteristics" in accent
        assert "modern_reference" in accent


def test_cultural_norms_database():
    """Verify cultural emotional norms have TTS impact."""
    for culture, data in CULTURAL_EMOTIONAL_NORMS.items():
        assert "display_rules" in data
        assert "grief_norms" in data
        assert "suppression_level" in data
        assert "tts_impact" in data
        assert isinstance(data["suppression_level"], float)
        assert 0.0 <= data["suppression_level"] <= 1.0


